.xt-root {
  /* 深色磨砂透感背景 */
  --xt-bg: rgba(15, 10, 15, 0.65);
  --xt-text: #ffffff;
  --xt-text-sub: #dddddd;
  --xt-text-muted: #888888;

  /* 恋爱主题色：淡粉色 */
  --xt-accent: #ff99bb;      
  --xt-accent-bg: rgba(255, 153, 187, 0.15);
  --xt-border: rgba(255, 255, 255, 0.2);
  --xt-glow-color: rgba(255, 153, 187, 0.5); /* 为 .glow 动画设置发光色 */

  --xt-radius: 4px; 
  --xt-font: 'Share Tech Mono', monospace, sans-serif;

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  border: 1px solid var(--xt-border);
  box-shadow: inset 0 0 30px rgba(0,0,0,0.3), 0 8px 32px rgba(0,0,0,0.4);
  letter-spacing: 1px;
}

/* 顶部文字 */
.xt-text-topHeader {
  color: var(--xt-accent);
  font-size: 10px;
  letter-spacing: 3px;
  border-bottom: 1px dashed var(--xt-border);
  padding-bottom: 5px;
}
.xt-text-topHeader::before { content: "♥ "; animation: pulse 1s infinite; }

