.xt-section-body { color: #dddddd; font-size: 13px; }
.xt-bar-track { background: rgba(255,255,255,0.1); border-radius: 2px; height: 6px; }
.xt-bar-fill { background: #ffffff; border-radius: 2px; }
.xt-grid-bar:nth-child(3) .xt-bar-fill { background: var(--xt-accent); box-shadow: 0 0 8px var(--xt-accent); }

