.xt-list-item { border-bottom: 1px solid rgba(255,255,255,0.05); color: #cccccc; font-size: 12px; }
.xt-list-check { display: none; }
.xt-list-item::before { content: "♥ "; color: var(--xt-accent); font-size: 10px; }

.xt-bubble-body {
  border-radius: 8px !important;
